from collections import Counter

corpus = ["deep learning is useful", "deep models learn", "learning uses data"]
tokens = [token for text in corpus for token in text.split()]
counts = Counter(tokens)
vocabulary = {"<PAD>": 0, "<UNK>": 1}
for token, _ in counts.most_common():
    if token not in vocabulary:
        vocabulary[token] = len(vocabulary)
print(vocabulary)

vocabulary = {"<PAD>": 0, "<UNK>": 1, "deep": 2, "learning": 3, "works": 4}

def encode(text, vocab):
    return [vocab.get(token, vocab["<UNK>"]) for token in text.lower().split()]

print(encode("deep learning works", vocabulary))
print(encode("deep models work", vocabulary))

vocabulary = {"<PAD>": 0, "<UNK>": 1, "deep": 2, "learning": 3}
id_to_token = {index: token for token, index in vocabulary.items()}

ids = [2, 3, 1]
tokens = [id_to_token[index] for index in ids]
print(tokens)
